import React from 'react';
import PropTypes from 'prop-types';
import { Calendar, Users, DollarSign } from 'lucide-react';

const RecentProjects = ({ projects = [] }) => {
  const getStatusColor = (status) => {
    switch (status) {
      case 'completed': return 'bg-green-500';
      case 'in_progress': return 'bg-blue-500';
      default: return 'bg-yellow-500';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'completed': return 'Terminé';
      case 'in_progress': return 'En cours';
      default: return 'En attente';
    }
  };

  // safe formatter for budgets (returns string)
  const formatBudget = (b) => {
    const num = typeof b === 'number' ? b : Number(b);
    if (!Number.isFinite(num)) return '0';
    try {
      return num.toLocaleString();
    } catch {
      return String(num);
    }
  };

  // safe formatter for dates (returns string)
  const formatDate = (d) => {
    if (!d) return 'N/A';
    const date = d instanceof Date ? d : new Date(d);
    if (isNaN(date.getTime())) return 'N/A';
    try {
      return date.toLocaleDateString();
    } catch {
      return date.toISOString().split('T')[0];
    }
  };

  // clamp progress
  const clampProgress = (p) => {
    const n = typeof p === 'number' ? p : Number(p);
    if (!Number.isFinite(n)) return 0;
    return Math.min(100, Math.max(0, Math.round(n)));
  };

  // guard projects array content
  const safeProjects = Array.isArray(projects) ? projects.filter(Boolean) : [];

  if (safeProjects.length === 0) {
    return (
      <div className="bg-white rounded-xl p-6 shadow-md border border-gray-100">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold text-gray-900">Projets Récents</h3>
        </div>
        <div className="text-gray-600">Aucun projet récent.</div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-xl p-6 shadow-md border border-gray-100">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-xl font-bold text-gray-900">Projets Récents</h3>
        <button className="text-blue-600 hover:text-blue-700 text-sm font-medium">
          Voir tout
        </button>
      </div>

      <div className="space-y-4">
        {safeProjects.map((project) => {
          const {
            id,
            name = 'Sans nom',
            deadline = null,
            team = 0,
            budget = 0,
            progress = 0,
            status = 'pending',
          } = project;

          const budgetStr = formatBudget(budget);
          const dateStr = formatDate(deadline);
          const prog = clampProgress(progress);

          return (
            <div
              key={id ?? Math.random()}
              className="flex items-center justify-between p-4 border border-gray-200 rounded-lg hover:bg-gray-50 transition duration-200 group"
            >
              <div className="flex items-center space-x-4 flex-1 min-w-0">
                <div className={`w-3 h-3 rounded-full ${getStatusColor(status)}`} />
                <div className="flex-1 min-w-0">
                  <h4 className="font-semibold text-gray-900 group-hover:text-blue-600 transition duration-200 truncate">
                    {name}
                  </h4>

                  <div className="flex items-center space-x-4 mt-1 text-sm text-gray-600">
                    <div className="flex items-center">
                      <Calendar className="h-3 w-3 mr-1" />
                      <span>{dateStr}</span>
                    </div>

                    <div className="flex items-center">
                      <Users className="h-3 w-3 mr-1" />
                      <span>{team} {team > 1 ? 'membres' : 'membre'}</span>
                    </div>

                    <div className="flex items-center">
                      <DollarSign className="h-3 w-3 mr-1" />
                      <span>{budgetStr} €</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex items-center space-x-4 ml-4">
                <div className="text-right min-w-32">
                  <div className="flex justify-between text-sm text-gray-600 mb-1">
                    <span>Progression</span>
                    <span>{prog}%</span>
                  </div>

                  <div className="w-32 bg-gray-200 rounded-full h-2">
                    <div
                      className={`h-2 rounded-full transition-all duration-300 ${getStatusColor(status)}`}
                      style={{ width: `${prog}%` }}
                    />
                  </div>

                  <span
                    className={`text-xs font-medium mt-1 inline-block px-2 py-1 rounded-full ${
                      status === 'completed' ? 'bg-green-100 text-green-800' :
                      status === 'in_progress' ? 'bg-blue-100 text-blue-800' :
                      'bg-yellow-100 text-yellow-800'
                    }`}
                  >
                    {getStatusText(status)}
                  </span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

RecentProjects.propTypes = {
  projects: PropTypes.arrayOf(PropTypes.object),
};

RecentProjects.defaultProps = {
  projects: [],
};

export default RecentProjects;
